import 'alert_players_stub.dart'
    if (dart.library.js_interop) 'alert_players_web.dart';

/// Where the chime is served from, relative to the page's base href
/// (`web/sounds/`, generated by `tools/make_order_sound.py`).
const newOrderChimeUrl = 'sounds/sfx_new_order.mp3';

/// One way of making the alert sound.
abstract interface class AlertPlayer {
  /// Called synchronously from the staff's tap so the browser lets this
  /// player sound later without a gesture (iOS Safari needs this).
  void prime();

  /// Completes once playback has started; throws if it cannot play.
  Future<void> play();
}

/// The new-order alert (P1-F02, ASSETS.md 4.5): the `sfx_new_order.mp3`
/// chime, or the generated tone if the file fails to load or play. Best
/// effort: it never throws, and the card highlight still shows the order.
class NewOrderSound {
  NewOrderSound({required AlertPlayer chime, required AlertPlayer fallback})
    : _chime = chime,
      _fallback = fallback;

  /// The browser's players (silent off the web).
  factory NewOrderSound.browser() => NewOrderSound(
    chime: chimePlayer(newOrderChimeUrl),
    fallback: tonePlayer(),
  );

  final AlertPlayer _chime;
  final AlertPlayer _fallback;

  /// The staff's one tap that turns sound on: unlocks both players and rings
  /// once as a check. Must be called directly from the tap handler; the chime
  /// starts synchronously, before any await.
  Future<void> enable() {
    _chime.prime();
    _fallback.prime();
    return play();
  }

  Future<void> play() async {
    try {
      await _chime.play();
    } on Object {
      try {
        await _fallback.play();
      } on Object {
        // Both failed; the highlight still shows the new order.
      }
    }
  }
}
